import socket, time
s = socket.create_connection(("127.0.0.2", 6667), timeout=5)
f = s.makefile("rw")
def send(line):
    f.write(line + "\n"); f.flush()
def drain(t=1.5):
    s.settimeout(t)
    out = []
    try:
        while True:
            line = f.readline()
            if not line: break
            out.append(line.rstrip())
    except socket.timeout:
        pass
    return out
send("NICK agent1")
send("USER agent1 0 * :agent1")
for line in drain(2): print(line)
send("JOIN #tips")
